M(tick, r"""
public static boolean mine(@PKG@.ZRegion r) {
  for (int i = 0; r.types != null && i < r.types.length; i++) {
    String t = r.types[i];
    if (t.equals("stone") || t.equals("rock") || t.equals("gem") || t.equals("crystals") || t.equals("copper") || t.equals("iron") || t.equals("gold")
        || t.equals("silver") || t.equals("thorium") || t.equals("cobalt") || t.equals("adamantite") || t.equals("mithril") || t.equals("onyxium")
        || t.equals("lead") || t.equals("chromium") || t.equals("slag") || t.equals("titanium")) return true;
  }
  return false;
}""")
