M(tick, r"""
public static int wandDraw(@REF@ ref, @ST@ st, java.util.UUID u, String w, int px, int pz) {
  java.util.ArrayList to = new java.util.ArrayList();
  to.add(ref);
  String[] ps = @PKG@.ZCfg.wandParticles();
  int n = 0;
  int[] s = @PKG@.ZWand.preview(u, w);
  if (s != null) n = n + emit(edges(new int[] { s[0], s[1], s[2], s[3] + 1, s[4] + 1, s[5] + 1 }, WAND_SEL_PTS), ps[0], to, st);
  @PKG@.ZRegion[] a = @PKG@.ZStore.INDEX.in(w);
  int boxes = 0;
  for (int i = 0; i < a.length && boxes < WAND_BOXES; i++) {
    int[] b = a[i].box;
    String pid = a[i].mode == 0 ? ps[1] : (a[i].mode == 2 ? ps[2] : (mine(a[i]) ? ps[4] : ps[3]));
    for (int j = 0; b != null && j + 5 < b.length && boxes < WAND_BOXES; j = j + 6) {
      if (px < b[j] - WAND_NEAR || px > b[j + 3] + WAND_NEAR || pz < b[j + 2] - WAND_NEAR || pz > b[j + 5] + WAND_NEAR) continue;
      n = n + emit(edges(new int[] { b[j], b[j + 1], b[j + 2], b[j + 3] + 1, b[j + 4] + 1, b[j + 5] + 1 }, WAND_BOX_PTS), pid, to, st);
      boxes++;
    }
  }
  return n;
}""")
