# update(text, rewrite keys, their old default, their new value, append keys, their values) -> Object[] { text, rows, kept } (= ZMig.update
# with this round's comment line over the appended block)
M(mig2, r"""
public static Object[] update(String text, String[] rk, String[] ro, String[] rn, String[] ak, String[] av) {
  String[] raw = text.split("\\n", -1);
  java.util.ArrayList l = new java.util.ArrayList();
  for (int i = 0; i < raw.length; i++) { String s0 = raw[i]; if (s0.endsWith("\\r")) s0 = s0.substring(0, s0.length() - 1); l.add(s0); }
  java.util.HashSet have = new java.util.HashSet();
  java.util.ArrayList rows = new java.util.ArrayList();
  StringBuilder kept = new StringBuilder();
  java.util.ArrayList out = new java.util.ArrayList();
  int k = 0;
  while (k < l.size()) {
    String s = (String) l.get(k);
    if (@PKG@.CfgFile.isComment(s)) { out.add(raw[k]); k++; continue; }
    int e = @PKG@.CfgFile.end(l, k);
    String key = @PKG@.CfgFile.key(s);
    if (key != null) have.add(key);
    int j = @PKG@.ZMig.idx(rk, key);
    if (j >= 0) {
      String v = @PKG@.CfgFile.value(l, k).trim();
      if (e == k && @PKG@.ZMig.norm(v).equals(@PKG@.ZMig.norm(ro[j]))) {
        String cr1 = raw[k].endsWith("\\r") ? "\\r" : "";
        out.add(s.substring(0, @PKG@.CfgFile.valStart(s)) + rn[j] + cr1);
        rows.add(key); rows.add(v); rows.add(rn[j]);
        k = e + 1;
        continue;
      }
      if (!@PKG@.ZMig.norm(v).equals(@PKG@.ZMig.norm(rn[j]))) kept.append(kept.length() > 0 ? ", " : "").append(key).append('=').append(@PKG@.CfgRows.oneLine(v));
    }
    for (int q = k; q <= e; q++) out.add(raw[q]);
    k = e + 1;
  }
  String cr = text.indexOf("\\r\\n") >= 0 ? "\\r" : "";
  java.util.ArrayList add = new java.util.ArrayList();
  for (int i = 0; i < ak.length; i++) {
    if (have.contains(ak[i])) continue;
    add.add(ak[i] + "=" + av[i] + cr);
    rows.add(ak[i]); rows.add(null); rows.add(av[i]);
  }
  if (!add.isEmpty()) {
    int at = out.size() - 1;
    if (at < 0) { out.add(""); at = 0; }
    if (((String) out.get(at)).length() != 0) { out.set(at, (String) out.get(at) + cr); out.add(""); at = out.size() - 1; }
    out.add(at, HEAD + cr);
    at++;
    for (int i = 0; i < add.size(); i++) { out.add(at, add.get(i)); at++; }
  }
  StringBuilder sb = new StringBuilder(text.length() + 256);
  for (int i = 0; i < out.size(); i++) { if (i > 0) sb.append('\\n'); sb.append((String) out.get(i)); }
  return new Object[] { sb.toString(), (String[]) rows.toArray(new String[0]), kept.toString() };
}""")
# the Server Setup -> Changes line (table rows regrow[x] / type[x]; field rows by their key) - Undo works on it
M(mig2, r"""
public static String logLine(String k, String o, String n) {
  boolean rg = k.startsWith("regrow.");
  boolean ty = k.startsWith("type.");
  String key = rg ? "regrow[" + k.substring(7) + "]" : (ty ? "type[" + k.substring(5) + "]" : k);
  String ov = o == null ? "(none)" : (rg ? o.replace(',', '|') : o);
  String nv = rg ? n.replace(',', '|') : n;
  return @PKG@.CfgLog.now() + "\\t" + WHO + "\\t-\\tmigration\\t" + key + "\\t" + @PKG@.CfgRows.oneLine(ov) + "\\t" + @PKG@.CfgRows.oneLine(nv) + "\\tok";
}""")
M(mig2, r"""
public static void mark(java.nio.file.Path m, String what) {
  try {
    java.nio.file.Files.createDirectories(m.getParent(), new java.nio.file.attribute.FileAttribute[0]);
    java.nio.file.Files.write(m, ("SkyyZones 0.3.2 one-time update (Mig032) done " + new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss").format(new java.util.Date()) + ": " + what + "\\n").getBytes("UTF-8"), new java.nio.file.OpenOption[0]);
  } catch (Throwable t) { @PKG@.ZCfg.warn("could not write " + m + " (the 0.3.2 update runs again at the next start - it changes nothing twice): " + t); }
}""")
# run(dir): "" = nothing done (marker there, or a failure: WARN, files untouched, the next start tries again); else the summary. A fresh
# folder (no types / regen / trees file yet) only gets the marker - the default files written next already carry the 0.3.2 rows
M(mig2, r"""
public static synchronized String run(java.nio.file.Path dir) {
  if (dir == null) return "";
  try {
    java.nio.file.Path m = dir.resolve(MARK);
    if (java.nio.file.Files.exists(m, new java.nio.file.LinkOption[0])) return "";
    ensure();
    int nf = FN.length;
    java.nio.file.Path[] fp = new java.nio.file.Path[nf];
    boolean[] has = new boolean[nf];
    for (int i = 0; i < nf; i++) { fp[i] = dir.resolve(FN[i]); has[i] = java.nio.file.Files.exists(fp[i], new java.nio.file.LinkOption[0]); }
    if (!has[0] && !has[1] && !has[3]) { mark(m, "a new folder - the default files carry the 0.3.2 rows"); return ""; }
    byte[][] ob = new byte[nf][];
    byte[][] nb = new byte[nf][];
    String[][] rows = new String[nf][];
    StringBuilder kept = new StringBuilder();
    for (int i = 0; i < nf; i++) {
      rows[i] = new String[0];
      if (!has[i]) continue;
      ob[i] = java.nio.file.Files.readAllBytes(fp[i]);
      Object[] u = update(new String(ob[i], "ISO-8859-1"), RK[i], RO[i], RN[i], AK[i], AV[i]);
      nb[i] = ((String) u[0]).getBytes("ISO-8859-1");
      rows[i] = (String[]) u[1];
      String kp = (String) u[2];
      if (kp.length() > 0) kept.append(kept.length() > 0 ? ", " : "").append(kp);
      if (!@PKG@.ZMig.sameAfter(ob[i], nb[i], rows[i])) {
        @PKG@.ZCfg.warn("the 0.3.2 update (Mig032) would change more than its own lines in " + FN[i] + " - the files are used as they are (the next start tries again)");
        return "";
      }
    }
    boolean any = false;
    for (int i = 0; i < nf; i++) if (nb[i] != null && !java.util.Arrays.equals(ob[i], nb[i])) any = true;
    int total = 0;
    if (any) {
      int[] fi = new int[nf];
      for (int i = 0; i < nf; i++) { fi[i] = @PKG@.ZMig.fileIdx(FN[i]); if (has[i] && fi[i] < 0) return ""; }
      @PKG@.CfgRows.HOME = dir.toAbsolutePath();
      if (@PKG@.CfgRows.LOG == null) @PKG@.CfgRows.LOG = @PKG@.ZCfg.LOG;
      @PKG@.CfgHist.init();
      @PKG@.CfgLog.init();
      String st = @PKG@.CfgHist.stamp();
      for (int i = 0; i < nf; i++) {
        if (nb[i] == null || java.util.Arrays.equals(ob[i], nb[i])) continue;
        @PKG@.CfgHist.snapshot(fi[i], ob[i], st, WHO, "before the 0.3.2 update (Mig032: natural gathering types, the big-tree fix)");
        if (!@PKG@.ZMig.saved(fi[i], ob[i])) {
          @PKG@.ZCfg.warn("the 0.3.2 update (Mig032) is NOT done: the old " + FN[i] + " could not be kept in " + @PKG@.CfgHist.DIR + " (the files are used as they are; the next start tries again)");
          return "";
        }
      }
      for (int i = 0; i < nf; i++) {   // each file's Changes lines right after ITS write (a failed later write never loses an earlier file's Undo lines)
        if (nb[i] == null || java.util.Arrays.equals(ob[i], nb[i])) continue;
        @PKG@.CfgRows.atomicWrite(fp[i], nb[i]);
        for (int j = 0; j + 2 < rows[i].length; j += 3) @PKG@.CfgLog.enqueue(logLine(rows[i][j], rows[i][j + 1], rows[i][j + 2]));
        @PKG@.CfgLog.flush();
        total = total + rows[i].length / 3;
      }
    }
    if (kept.length() > 0) @PKG@.ZCfg.info("the 0.3.2 update keeps hand-edited lines as they are: " + kept);
    String msg = "one-time 0.3.2 update (Mig032): " + total + " lines changed / added" + (kept.length() > 0 ? ", kept (hand-edited): " + kept : "") + " (old files in config-history; Server Setup -> Changes can undo each line)";
    mark(m, msg);
    LAST = msg;
    @PKG@.ZCfg.info(msg);
    return msg;
  } catch (Throwable t) {
    @PKG@.ZCfg.warn("the 0.3.2 update (Mig032) failed - the files are used as they are (the next start tries again): " + t);
    return "";
  }
}""")

